sealed interface UiState<out T> {
  data object Loading : UiState<Nothing>
  data class Success<T>(val data: T) : UiState<T>
  data class Error(val cause: Throwable) : UiState<Nothing>
}

val users: UiState<List<User>> = UiState.Loading      // Nothing fits anywhere
val profile: UiState<User> = UiState.Loading

fun render(state: UiState<User>) = when (state) {     // exhaustive, no else
  UiState.Loading -> showSpinner()
  is UiState.Success -> showUser(state.data)
  is UiState.Error -> showError(state.cause)
}

